head.script:
scwin.grid1_ongroupby = function(options) {
    return false;
};
scwin.grid1_groupbyFilterBoxFormatter = function(data) {
    var label = "";
    var labelArr = [];
    for (var i = 0; i < data.length; i++) {
        var s_label = "";
        var obj = data[i];
        var header = obj.header;
        var filter = obj.filter;
        for (var j = 0; j < filter.length; j++) {
            if (filter[j].gate)
                s_label = s_label + " " + filter[j].gate + " ";
            var values = filter[j].values;
            if (values.join)
                values = "[" + values.join(" // ") + "]";
            s_label = s_label + filter[j].operator + " " + values;
        }
        s_label = "(" + header + " " + s_label + ")";
        labelArr.push(s_label);
    }
    label = labelArr.join(" % ");
    return label;
};
scwin.onpageload = function() {
    window.arr = [];
    for (window.i = 0; i < 500; i++) {
        for (window.j = 0; j < 7; j++) {
            arr.push(Math.floor((Math.random() * (30 - 1 + 1)) + 1));
        }
    }
    /*
    window.arr = [];
    arr.push( 1 );
    arr.push( 2 );
    arr.push( 3 );
    arr.push( 4 );
    arr.push( 5 );
    arr.push( 6 );
    arr.push( 7 );
    arr.push( 8 );
    arr.push( 9 );
    arr.push( 10 );
    arr.push( 11 );
    arr.push( 12 );
    arr.push( 13 );
    arr.push( 14 );
    */
    dataList1.setData(arr);
    input1.setValue(" [ 0, 1, 2] ");
    input2.setValue(" [ 1, 0, 1] ");
    input3.setValue(" { inputType:'expression', expression: 'toggle()+depthStr()+\"    [ \"+count()+\" 건 ]\"', align: 'left', colSpan:9} ");
    input4.setValue("");
    input5.setValue("");
    input6.setValue(" {colSpan:7} ");
    input7.setValue(" {hidden:true} ");
    input8.setValue(' {"category1":["1","2","3"], "category2":["1","2","3"]} ');
    input9.setValue(" [ {value:'합계'}, {inputType:'expression', expression:'SUM(\"category7\")'} ] ");
    // data: @type:array, @desc: groupby filterbox 에 추가되는 filter 정보를 담고 있다.
    // | header: @type:string, @desc: filter 대상이 되는 열의 헤더 label
    // | filter: @type:array, @desc: filter 조건을 포함
    // | | operator: @type:string, @desc: filter 연산자
    // | | values: @type:object, @desc: filter 비교값 - 대상이 다수일 경우에는 array 형태로 제공
    // | | gate: @type:string, @desc: filter 접속어 [undefiend, and, or]
}

scwin.__isReplaceStringFilter = function() {
    if (WebSquare.wUnit.getJq("#grid1_groupbyFilterBox_select_label")) {
        //return WebSquare.wUnit.getJq("#grid1_groupbyFilterBox_select_label").text() == "(category1 in [1 // 2 // 3]) % (category2 in [2 // 3])";
		let targetStr = WebSquare.wUnit.getJq("#grid1_groupbyFilterBox_select_label").text();

		let hasDoubleSlash = targetStr.indexOf("//") > -1;
		let hasPercent = targetStr.indexOf("%") > -1;
		return hasDoubleSlash && hasPercent;
    }
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1000");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");

    WebSquare.wUnit.addCommand("assert", "scwin.__isReplaceStringFilter()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

